-- =====================================================================
--  CRD Tracker  —  PostgreSQL schema + data
--  Source        : Monica_CRD_Tracker_Masterlist_.csv (Masterlist tab)
--  Generated     : 2026-07-20 02:05
--  Target        : PostgreSQL 12+
--
--  MODEL
--    revision_code : dimension of CRD revision codes (A,B,...,BY). 'seq' is the
--                    decoded ordinal (bijective base-26) so revisions sort
--                    correctly. 'crd_date' is intentionally EMPTY — if a letter
--                    maps to a real Customer/Commit Required Date, fill it here.
--    line          : one row per tracked line item ('No'), L11 level.
--    component     : L10 components under a line (1..many). Holds the per-row
--                    'Current CRD (TE)' + 'Date update'.
--    week_status   : weekly CRD revision history, one row per (line, work-week)
--                    that had a code. Verified identical across a line's L10
--                    sub-rows, so it is stored once at the line level.
--
--  NOTES
--    * '-' cells in the sheet mean "no CRD that week" and are OMITTED here.
--    * Dates parsed from mixed formats (d-Mon-yy, m/d/YYYY) into DATE.
--    * Re-runnable: drops & recreates the crd.* objects.
--
--  LOAD (run once Postgres is installed on 10.251.231.79):
--    createdb crd_tracker            -- or: CREATE DATABASE crd_tracker;
--    psql -h 10.251.231.79 -U <user> -d crd_tracker -f crd_tracker_postgres.sql
-- =====================================================================

BEGIN;

CREATE SCHEMA IF NOT EXISTS crd;
SET search_path TO crd, public;

DROP VIEW  IF EXISTS crd.v_current_crd   CASCADE;
DROP VIEW  IF EXISTS crd.v_line_component CASCADE;
DROP TABLE IF EXISTS crd.week_status  CASCADE;
DROP TABLE IF EXISTS crd.component    CASCADE;
DROP TABLE IF EXISTS crd.line         CASCADE;
DROP TABLE IF EXISTS crd.revision_code CASCADE;

-- ---------- dimension: CRD revision codes ----------
CREATE TABLE crd.revision_code (
    code      varchar(4)  PRIMARY KEY,
    seq       integer     NOT NULL UNIQUE,
    crd_date  date,                       -- fill in if code maps to a real date
    note      text
);
COMMENT ON TABLE  crd.revision_code IS 'CRD revision codes; seq = decoded ordinal for sorting; crd_date optional lookup.';

-- ---------- line (L11 / "No") ----------
CREATE TABLE crd.line (
    id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    line_no     integer NOT NULL UNIQUE,
    gen         numeric(5,2),
    l11_msf     varchar(30),
    l11_sku     varchar(30),
    crd_number  varchar(30),
    wts_ticket  varchar(20),
    wts_link    text
);
COMMENT ON TABLE crd.line IS 'Tracked line item (sheet column "No"), L11 assembly level.';

-- ---------- component (L10) ----------
CREATE TABLE crd.component (
    id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    line_id         integer NOT NULL REFERENCES crd.line(id) ON DELETE CASCADE,
    l10_msf         varchar(30),
    l10_sku         varchar(30),
    current_crd_te  varchar(4) REFERENCES crd.revision_code(code),
    date_update     date
);
COMMENT ON TABLE crd.component IS 'L10 component under a line; current_crd_te is the TE-recorded revision (may lag week_status).';

-- ---------- week_status (weekly CRD history, line level) ----------
CREATE TABLE crd.week_status (
    id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    line_id       integer  NOT NULL REFERENCES crd.line(id) ON DELETE CASCADE,
    iso_year      smallint NOT NULL,
    work_week     smallint NOT NULL,
    week_label    varchar(10) NOT NULL,
    week_start_date date,
    crd_code      varchar(4) NOT NULL REFERENCES crd.revision_code(code),
    crd_seq       integer NOT NULL,       -- denormalized ordinal for fast ordering
    UNIQUE (line_id, iso_year, work_week)
);
COMMENT ON TABLE crd.week_status IS 'Weekly CRD revision per line; one row per (line, work-week) that had a code.';


