-- ---------- realign identity sequences ----------
SELECT setval(pg_get_serial_sequence('crd.line','id'),      (SELECT MAX(id) FROM crd.line));
SELECT setval(pg_get_serial_sequence('crd.component','id'), (SELECT MAX(id) FROM crd.component));
SELECT setval(pg_get_serial_sequence('crd.week_status','id'),(SELECT MAX(id) FROM crd.week_status));

-- ---------- indexes ----------
CREATE INDEX ix_component_line   ON crd.component(line_id);
CREATE INDEX ix_component_l10sku ON crd.component(l10_sku);
CREATE INDEX ix_component_l10msf ON crd.component(l10_msf);
CREATE INDEX ix_line_crdno       ON crd.line(crd_number);
CREATE INDEX ix_line_l11sku      ON crd.line(l11_sku);
CREATE INDEX ix_line_wts         ON crd.line(wts_ticket);
CREATE INDEX ix_ws_line          ON crd.week_status(line_id);
CREATE INDEX ix_ws_week          ON crd.week_status(iso_year, work_week);
CREATE INDEX ix_ws_code          ON crd.week_status(crd_code);

-- ---------- convenience views ----------
-- Latest CRD revision per line, derived from the weekly history.
CREATE VIEW crd.v_current_crd AS
SELECT DISTINCT ON (ws.line_id)
       l.line_no, l.gen, l.l11_msf, l.l11_sku, l.crd_number, l.wts_ticket,
       ws.week_label, ws.iso_year, ws.work_week, ws.week_start_date,
       ws.crd_code AS current_crd_code, ws.crd_seq AS current_crd_seq
FROM   crd.week_status ws
JOIN   crd.line l ON l.id = ws.line_id
ORDER  BY ws.line_id, ws.week_start_date DESC NULLS LAST, ws.crd_seq DESC;

-- Flat line + component listing with each level's current CRD.
CREATE VIEW crd.v_line_component AS
SELECT l.line_no, l.gen, l.l11_msf, l.l11_sku, l.crd_number, l.wts_ticket, l.wts_link,
       c.l10_msf, c.l10_sku, c.current_crd_te, c.date_update
FROM   crd.line l
JOIN   crd.component c ON c.line_id = l.id
ORDER  BY l.line_no, c.id;

COMMIT;
